  await page.click('#submit');
  await page.waitForURL('/dashboard');
  loggedInPage = page;
});

test('view users', async () => {
  await loggedInPage.goto('/admin/users');
  await expect(loggedInPage.locator('.user-row')).toHaveCount(5);
});

